-- Owner's studio photos, second batch (2026-11-10), served from /menu/<slug>.webp. Keeps any photo already uploaded in Admin.
UPDATE menu_items SET image_url = '/menu/' || slug || '.webp', updated_at = now()
WHERE image_url IS NULL AND slug IN ('broccoli-corn-salad-bowl', 'chicken-shawarma-meal-bowl', 'chocolate-smoothie', 'classic-egg-sandwich', 'classic-french-salad-bowl-veg', 'creamy-italian-herb-pasta-bowl', 'cucumber-and-avocado-salad-bowl', 'cucumber-watermelon-salad-bowl', 'egg-akuri-on-sourdough', 'exotic-apple-salad-bowl', 'fresh-zucchini-noodles-salad-bowl', 'healthy-quinoa-salad-bowl', 'italian-pesto-pasta-bowl', 'mediterranean-salad-bowl', 'mexi-burrito-red-rice-bowl', 'red-sauce-pasta-bowl', 'spicy-tofu-protein-salad-bowl', 'sprouts-protein-salad-bowl', 'tandoori-grill', 'watermelon-beetroot-lime');
